BEGIN;
CREATE SCHEMA delivery_test;CREATE FUNCTION delivery_test.assert(ok boolean,msg text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'ASSERT: %',msg;END IF;END $$;CREATE FUNCTION delivery_test.denied(statement text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN BEGIN EXECUTE statement;EXCEPTION WHEN OTHERS THEN RETURN;END;RAISE EXCEPTION 'Expected rejection: %',statement;END $$;GRANT USAGE ON SCHEMA delivery_test TO anon,authenticated;GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA delivery_test TO anon,authenticated;
INSERT INTO auth.users(id,email) VALUES('2b000000-0000-4000-8000-000000000001','delivery@example.invalid');INSERT INTO public.companies(id,nome,created_by) VALUES('1b000000-0000-4000-8000-000000000001','Delivery fixture','2b000000-0000-4000-8000-000000000001'),('1b000000-0000-4000-8000-000000000002','Other fixture','2b000000-0000-4000-8000-000000000001');
INSERT INTO public.company_members(company_id,user_id,role,maintenance_role,created_by) VALUES('1b000000-0000-4000-8000-000000000001','2b000000-0000-4000-8000-000000000001','administrador','admin_empresa','2b000000-0000-4000-8000-000000000001');
INSERT INTO public.veiculos(id,company_id,placa,tipo,marca_modelo,km_atual,ano_fabricacao,ano_modelo,chassi,renavam) VALUES('3b000000-0000-4000-8000-000000000001','1b000000-0000-4000-8000-000000000001','EXL0001','caminhao','Volvo FH',1000,2022,2023,'9BWZZZ377VT004251','12345678901');
SELECT set_config('request.jwt.claim.sub','2b000000-0000-4000-8000-000000000001',true);
INSERT INTO public.maintenance_partners(id,company_id,razao_social,whatsapp,onboarding_profile) VALUES('4b000000-0000-4000-8000-000000000001','1b000000-0000-4000-8000-000000000001','Delivery workshop','11987654321','{"prazo_entrega_dias":3}');

INSERT INTO public.maintenance_partners(id,company_id,razao_social,whatsapp,status) VALUES('4b000000-0000-4000-8000-000000000002','1b000000-0000-4000-8000-000000000001','Second workshop','21987654321','ativo'),('4b000000-0000-4000-8000-000000000003','1b000000-0000-4000-8000-000000000001','No contact',NULL,'ativo'),('4b000000-0000-4000-8000-000000000004','1b000000-0000-4000-8000-000000000001','Inactive workshop','31987654321','inativo'),('4b000000-0000-4000-8000-000000000005','1b000000-0000-4000-8000-000000000002','Other company','41987654321','ativo');
SET LOCAL ROLE authenticated;
SELECT set_config('delivery_test.id',public.maintenance_order_command('1b000000-0000-4000-8000-000000000001','create','{"vehicle_id":"3b000000-0000-4000-8000-000000000001","partner_id":"4b000000-0000-4000-8000-000000000001","tipo":"corretiva","prioridade":"media","descricao_problema":"Repair needed","km_abertura":1000}')->>'id',true);
SELECT delivery_test.assert((SELECT count(*)=3 FROM public.maintenance_order_dispatches WHERE order_id=current_setting('delivery_test.id')::uuid),'all active workshops in same company queued');
SELECT public.maintenance_order_dispatch('1b000000-0000-4000-8000-000000000001','select_partner',jsonb_build_object('id',current_setting('delivery_test.id'),'version',(SELECT version FROM public.maintenance_orders WHERE id=current_setting('delivery_test.id')::uuid),'partner_id','4b000000-0000-4000-8000-000000000002'));
SELECT public.maintenance_order_command('1b000000-0000-4000-8000-000000000001','item_save',jsonb_build_object('id',current_setting('delivery_test.id'),'version',(SELECT version FROM public.maintenance_orders WHERE id=current_setting('delivery_test.id')::uuid),'tipo','peca','descricao','Part with supplier NCM','quantidade',1,'valor_unitario',450,'ncm','0101.21.00'));
SELECT delivery_test.assert((SELECT ncm='01012100' FROM public.maintenance_order_items WHERE order_id=current_setting('delivery_test.id')::uuid),'NCM persisted with leading zero');
SELECT delivery_test.assert(public.maintenance_order_dispatch('1b000000-0000-4000-8000-000000000001','document',jsonb_build_object('id',current_setting('delivery_test.id')))->'items'->0->>'ncm'='01012100','document includes NCM');
SELECT delivery_test.denied($q$SELECT public.maintenance_order_dispatch('1b000000-0000-4000-8000-000000000001','select_partner',jsonb_build_object('id',current_setting('delivery_test.id'),'version',(SELECT version FROM public.maintenance_orders WHERE id=current_setting('delivery_test.id')::uuid),'partner_id','4b000000-0000-4000-8000-000000000001'))$q$);
SELECT delivery_test.denied($q$SELECT public.maintenance_order_command('1b000000-0000-4000-8000-000000000001','item_save',jsonb_build_object('id',current_setting('delivery_test.id'),'version',(SELECT version FROM public.maintenance_orders WHERE id=current_setting('delivery_test.id')::uuid),'tipo','peca','descricao','Invalid NCM','quantidade',1,'valor_unitario',1,'ncm','abc'))$q$);
SELECT set_config('delivery_test.dispatch',(SELECT id::text FROM public.maintenance_order_dispatches WHERE order_id=current_setting('delivery_test.id')::uuid AND recipient_partner_id='4b000000-0000-4000-8000-000000000001'),true);
SELECT set_config('delivery_test.claim',public.maintenance_order_dispatch('1b000000-0000-4000-8000-000000000001','claim',jsonb_build_object('id',current_setting('delivery_test.id'),'kind','abertura','dispatch_id',current_setting('delivery_test.dispatch')))::text,true);
SELECT delivery_test.assert(current_setting('delivery_test.claim')::jsonb->>'phone'='5511987654321','recipient uses its own contact');
SELECT delivery_test.assert(jsonb_array_length(current_setting('delivery_test.claim')::jsonb->'snapshot'->'items')=0 AND (current_setting('delivery_test.claim')::jsonb->'snapshot'->'order'->>'valor_total')::numeric=0,'other workshop prices never broadcast');
SELECT delivery_test.assert(current_setting('delivery_test.claim')::jsonb->'snapshot'->'partner'->>'nome'='Delivery workshop','individualized recipient snapshot');
SELECT public.maintenance_order_dispatch('1b000000-0000-4000-8000-000000000001','finish',jsonb_build_object('id',current_setting('delivery_test.id'),'kind','abertura','token',current_setting('delivery_test.claim')::jsonb->>'token','status','accepted','message_id','fixture-rfq'));
SELECT delivery_test.assert((SELECT count(*)=1 FROM public.maintenance_messages WHERE order_id=current_setting('delivery_test.id')::uuid AND partner_id='4b000000-0000-4000-8000-000000000001'),'dispatch to non-execution workshop audited');
SELECT delivery_test.assert(public.maintenance_order_dispatch('1b000000-0000-4000-8000-000000000001','claim',jsonb_build_object('id',current_setting('delivery_test.id'),'kind','abertura','dispatch_id',current_setting('delivery_test.dispatch')))->>'status'='accepted','accepted individual send is idempotent');
SELECT delivery_test.assert(public.maintenance_order_dispatch('1b000000-0000-4000-8000-000000000001','claim',jsonb_build_object('id',current_setting('delivery_test.id'),'kind','abertura','dispatch_id',(SELECT id FROM public.maintenance_order_dispatches WHERE order_id=current_setting('delivery_test.id')::uuid AND recipient_partner_id='4b000000-0000-4000-8000-000000000003')))->>'status'='unavailable','missing contact is recorded without sending');
SELECT public.maintenance_order_command('1b000000-0000-4000-8000-000000000001','budget',jsonb_build_object('id',current_setting('delivery_test.id'),'version',(SELECT version FROM public.maintenance_orders WHERE id=current_setting('delivery_test.id')::uuid),'decisao','aprovado','observacao','Supplier quoted five calendar days','prazo_entrega_dias',5));
SELECT delivery_test.assert((SELECT recipient_partner_id='4b000000-0000-4000-8000-000000000002' FROM public.maintenance_order_dispatches WHERE order_id=current_setting('delivery_test.id')::uuid AND kind='aprovacao'),'only selected workshop receives approval');
SELECT delivery_test.assert((SELECT prazo_entrega_dias=5 AND previsao_entrega=((prazo_base_aprovacao_em AT TIME ZONE 'America/Sao_Paulo')+interval '5 days') AT TIME ZONE 'America/Sao_Paulo' FROM public.maintenance_orders WHERE id=current_setting('delivery_test.id')::uuid),'forecast starts at approval using agreed calendar days');
SELECT delivery_test.assert((SELECT count(*)=0 FROM public.maintenance_order_dispatches WHERE order_id=current_setting('delivery_test.id')::uuid AND kind='abertura' AND status='pending'),'remaining quotes obsolete after approval');
SELECT delivery_test.denied($q$SELECT public.maintenance_order_dispatch('1b000000-0000-4000-8000-000000000002','list',jsonb_build_object('id',current_setting('delivery_test.id'),'kind','abertura'))$q$);
RESET ROLE;ROLLBACK;
